33	/// How to emit whitespace.
34	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
35	pub enum Whitespace {
36	    /// Ensures that whitespace that would otherwise be collapsed by HTML
37	    /// rendering engines[^1] is protected by spans with `white-space:
38	    /// pre-wrap`. The affected by whitespace are ASCII spaces and ASCII tabs.
39	    ///
40	    /// Tries to emit spans only when necessary.
41	    /// - ASCII tabs and consecutive sequences of spaces and/or tabs are always
42	    ///   wrapped in spans in this mode. This happens directly during
43	    ///   conversion.
44	    /// - Single ASCII spaces are only wrapped if they aren't supported by
45	    ///   normal elements on both sides. This happens in a separate pass that
46	    ///   runs for the whole block-level context as doing this properly needs
47	    ///   lookahead and lookbehind across different levels of the element
48	    ///   hierarchy.
49	    ///
50	    /// [^1]: <https://www.w3.org/TR/css-text-3/#white-space-rules>
51	    Normal,
52	    /// The whitespace is emitted as-is. This happens in
53	    /// - `<pre>` elements as they already have `white-space: pre`,
54	    /// - raw and escapable raw text elements as normal white space rules do not
55	    ///   apply to them.
56	    Pre,
57	}
