250	/// Handles arbitrary text while taking care that no whitespace within will be
251	/// collapsed by browsers.
252	fn handle_text(converter: &mut Converter, text: EcoString, span: Span) {
253	    /// Special kinds of characters.
254	    #[derive(Debug, Copy, Clone, Eq, PartialEq)]
255	    enum Kind {
256	        /// ASCII space.
257	        Space,
258	        /// ASCII tab.
259	        Tab,
260	        /// CR, LF, or CR + LF.
261	        Newline,
262	        /// A Unicode default-ignorable. Does not protect spaces from
263	        /// collapsing.
264	        Ignorable,
265	    }
266	
267	    impl Kind {
268	        fn of(c: char) -> Option<Kind> {
269	            match c {
270	                ' ' => Some(Kind::Space),
271	                '\t' => Some(Kind::Tab),
272	                '\r' | '\n' => Some(Kind::Newline),
273	                c if is_default_ignorable(c) => Some(Kind::Ignorable),
274	                _ => None,
275	            }
276	        }
277	    }
278	
279	    if converter.whitespace == Whitespace::Pre {
280	        converter.push(HtmlNode::Text(text, span));
281	        return;
282	    }
283	
284	    let mut emitted = 0;
285	    let mut prev_kind = None;
286	
287	    for (i, c) in text.char_indices() {
288	        let kind = Kind::of(c);
289	        let prev_kind = prev_kind.replace(kind);
290	        let Some(kind) = kind else { continue };
291	
292	        // A space that is surrounded by normal (i.e. not special) characters is
293	        // already protected and doesn't need further treatment.
294	        if kind == Kind::Space
295	            && let Some(None) = prev_kind
296	            && let Some(after) = text[i + 1..].chars().next()
297	            && Kind::of(after).is_none()
298	        {
299	            continue;
300	        }
301	
302	        // Emit the unspecial text up to the special character.
303	        if emitted < i {
304	            converter.push_text(&text[emitted..i], span);
305	            emitted = i;
306	        }
307	
308	        // Process the special character.
309	        match kind {
310	            Kind::Space => converter.push_text(' ', span),
311	            Kind::Tab => converter.push_text('\t', span),
312	            Kind::Newline => {
313	                if c == '\r' && text[i + 1..].starts_with('\n') {
314	                    // Skip the CR because the LF will already turn into
315	                    // a `<br>`.
316	                    emitted += 1;
317	                    continue;
318	                }
319	                converter.push(HtmlElement::new(tag::br).spanned(span));
320	            }
321	            Kind::Ignorable => converter.push_text(c, span),
322	        }
323	        emitted += c.len_utf8();
324	    }
325	
326	    // Push the remaining unspecial text.
327	    if emitted < text.len() {
328	        converter.push_text(
329	            // Try to reuse the `EcoString` if possible.
330	            if emitted == 0 { text } else { text[emitted..].into() },
331	            span,
332	        );
333	    }
334	}
