371	/// Ensures a lone HTML element/frame renders inline.
372	///
373	/// Paragraphs only allow "Phrasing content". The default display properties
374	/// that exists for valid phrasing content are `none`, `inline`, `inline-block`,
375	/// `contents`, `ruby`, and `inline math`. These can all be left as-is.
376	///
377	/// If, however, the `display` property was set to something like `block`
378	/// through a Typst `block` element, we need to unset it. Further, if a math
379	/// element has its `display` attribute set to `block`, then we need to
380	/// override it.
381	fn make_inline_level(node: &mut HtmlNode) {
382	    let mode = if let HtmlNode::Element(element) = node
383	        && element.tag == tag::mathml::math
384	        && element.attrs.get(attr::mathml::display).is_some_and(|v| v == "block")
385	    {
386	        Some(property::Display::InlineMath)
387	    } else {
388	        None
389	    };
390	    set_display(node, mode);
391	}
