393	/// Processes a block element.
394	fn handle_block(
395	    converter: &mut Converter,
396	    elem: &Packed<BlockElem>,
397	    styles: StyleChain,
398	) -> SourceResult<()> {
399	    let body = match elem.body.get_ref(styles) {
400	        None => None,
401	        Some(BlockBody::Content(body)) => Some(body),
402	        // These are only generated by native `typst-layout` show rules.
403	        Some(BlockBody::SingleLayouter(_) | BlockBody::MultiLayouter(_)) => {
404	            bail!(
405	                elem.span(),
406	                "blocks with layout routines should not occur in \
407	                 HTML export – this is a bug";
408	            )
409	        }
410	    };
411	
412	    let mut children = EcoVec::new();
413	    if let Some(body) = body {
414	        children = html_block_fragment(
415	            converter.engine,
416	            body,
417	            converter.locator.next(&elem.span()),
418	            styles,
419	            converter.whitespace,
420	        )?;
421	
422	        if let Some(node) = to_lone_element(&mut children)
423	            && make_block_level(node).is_ok()
424	        {
425	            converter.extend(children);
426	            return Ok(());
427	        }
428	    }
429	
430	    converter.push(
431	        // TODO: This is rather incomplete.
432	        HtmlElement::new(tag::div)
433	            .with_children(children)
434	            .spanned(elem.span()),
435	    );
436	
437	    Ok(())
438	}
