488	/// Indicates that an element can be made block-level with a `display` property.
489	#[derive(Debug, Copy, Clone)]
490	struct Unblockable;
491	
492	/// Whether, apart from tags, the nodes comprise a single element or frame.
493	fn to_lone_element(nodes: &mut EcoVec<HtmlNode>) -> Option<&mut HtmlNode> {
494	    let (start, end) = nodes.split_prefix_suffix(|node| matches!(node, HtmlNode::Tag(_)));
495	    matches!(&nodes[start..end], [HtmlNode::Element(_) | HtmlNode::Frame(_)])
496	        .then(|| &mut nodes.make_mut()[start])
497	}
498	
499	/// Sets the CSS `display` property for an element or frame.
500	fn set_display(node: &mut HtmlNode, display: Option<property::Display>) {
501	    let css = match node {
502	        HtmlNode::Element(element) => &mut element.css,
503	        HtmlNode::Frame(frame) => &mut frame.css,
504	        _ => return,
505	    };
506	    match display {
507	        Some(display) => css.push("display", display.as_str()),
508	        None => css.remove("display"),
509	    }
510	}
